linux-laptop.text:
# Rendered by ranch-radio from hosts/linux-laptop.json. Edit that file, then `ranch-radio install`.
# WirePlumber reads this at start: systemctl --user restart wireplumber.
monitor.alsa.rules = [
  # QMX transmit audio
  {
    matches = [ { node.name = "~alsa_output.usb-QRP_Labs_QMX_Transceiver-02.analog-stereo*" } ]
    actions = {
      update-props = {
        node.name = "alsa_output.usb-QRP_Labs_QMX_Transceiver-02.analog-stereo"
        priority.session = 100
      }
    }
  }
  # QMX receive audio
  {
    matches = [ { node.name = "~alsa_input.usb-QRP_Labs_QMX_Transceiver-02.analog-stereo*" } ]
    actions = {
      update-props = {
        node.name = "alsa_input.usb-QRP_Labs_QMX_Transceiver-02.analog-stereo"
        priority.session = 100
      }
    }
  }
]

